  // which is the only thing this module used to do.
  const GRIND_TARGETS = {
    gold: 1,
    diamond: 2,
    ruby: 3
  };
  const GRIND_TARGET_FALLBACK = "ruby";
  class AutoGrind {
    moduleName="autoGrind";
    client;
    grindAngle=null;
    constructor(client2) {
      this.client = client2;
    }
    // Each slot carries its own target, so the primary can be taken to ruby
    // while the hammer stops at gold, or the other way round. weaponType is the
    // slot the rest of the module already speaks in: 0 primary, 1 secondary.
    targetVariant(weaponType) {
      const chosen = weaponType === 1 ? Settings_default._autoGrindTargetSecondary : Settings_default._autoGrindTargetPrimary;
      const target = GRIND_TARGETS[chosen];
      return target === undefined ? GRIND_TARGETS[GRIND_TARGET_FALLBACK] : target;
    }
    // A slot only counts against "done" when it holds something worth grading:
    // the secondary grinds with the great hammer and nothing else, and the
    // stick is the one primary this module refuses to swing. A slot that cannot
    // be ground is satisfied rather than blocking, otherwise carrying no hammer
    // left this permanently unfinished and kept the module awake for nothing.
    isFullyUpgraded() {
      const {myPlayer: myPlayer} = this.client;
      const primary = myPlayer.getItemByType(0);
      const secondary = myPlayer.getItemByType(1);
      const secondaryDone = secondary !== 10 || myPlayer.getWeaponVariant(secondary).current >= this.targetVariant(1);
      const primaryDone = primary === 8 || myPlayer.getWeaponVariant(primary).current >= this.targetVariant(0);
      return secondaryDone && primaryDone;
    }
    getGrindAction(nearestTurret) {
      const {myPlayer: myPlayer, _ModuleHandler: ModuleHandler} = this.client;
      if (!nearestTurret) return null;
      const primary = myPlayer.getItemByType(0);
      const secondary = myPlayer.getItemByType(1);
      const useTank = ModuleHandler.canBuy(0, 40);
      let weaponType = null;
      if (secondary === 10 && myPlayer.getWeaponVariant(secondary).current < this.targetVariant(1)) {
        weaponType = 1;
      } else if (primary !== 8 && myPlayer.getWeaponVariant(primary).current < this.targetVariant(0)) {
        weaponType = 0;
      }
      if (weaponType === null) return null;
      if (weaponType === 1) {
        return {
          weapon: 1,
          hat: useTank ? 40 : 0
        };
      } else if (weaponType === 0) {
        const primaryDmg = myPlayer.getBuildingDamage(primary, useTank);
        if (secondary === 10) {
          const secondaryDmg = myPlayer.getBuildingDamage(secondary, useTank);
          if (nearestTurret.health > primaryDmg + secondaryDmg) {
            return {
              weapon: 1,
              hat: useTank ? 40 : 0
            };
          } else if (nearestTurret.health > primaryDmg) {
            return {
              weapon: 1,
              hat: 0
            };
          } else {
            return {
              weapon: 0,
              hat: useTank ? 40 : 0
            };
          }
        } else {
          return {
            weapon: 0,
            hat: useTank ? 40 : 0
          };
        }
      }
      return null;
    }
    placeTurret(angle) {
      const {myPlayer: myPlayer, ObjectManager: ObjectManager2, _ModuleHandler: ModuleHandler} = this.client;
      const id = myPlayer.getItemByType(8);
      const position = myPlayer.getPlacePosition(myPlayer.pos.future, id, angle);
      if (!ObjectManager2.canPlaceItem(id, position)) {
        return false;
      }
      ModuleHandler.requestPlace(8, angle, "autoGrind");
      if (!Array.isArray(ModuleHandler.placeAngles[1])) {
        ModuleHandler.placeAngles[1] = [];
      }
      ModuleHandler.placeAngles[0] = 8;
      ModuleHandler.placeAngles[1].push(angle);
      return true;
    }
    postTick() {
      const {_ModuleHandler: ModuleHandler, EnemyManager: EnemyManager2, myPlayer: myPlayer, ObjectManager: ObjectManager2} = this.client;
      // Idle while there is nothing to grind, rather than switching itself off.
      // Turning the setting off here meant raising a target, or picking up a
      // weapon that still needed grading, left the module silently disabled
      // with no sign of it but an unticked box.
      if (this.isFullyUpgraded()) {
        this.grindAngle = null;
        return;
      }
      if (!Settings_default._autoGrind || ModuleHandler.moduleActive || ModuleHandler.healedOnce || myPlayer.speed > 5) {
        this.grindAngle = null;
        return;
      }
      const {autoMill: autoMill, reloading: reloading} = ModuleHandler.staticModules;
      if (autoMill.isActive) return;
      const farmItem = myPlayer.getItemByType(8);
      if (farmItem !== 17 && farmItem !== 22) return;
      const nearestEnemy = EnemyManager2.nearestEnemy;
      if (nearestEnemy !== null && myPlayer.collidingSimple(nearestEnemy, 400)) return;
      let sumX = 0, sumY = 0, count = 0;
      let nearestTurret = null, nearestDist = Infinity;
      ObjectManager2.grid2D.query(myPlayer.pos.current.x, myPlayer.pos.current.y, 3, objID => {
        const obj = ObjectManager2.objects.get(objID);
        if (obj && (obj.type === 17 || obj.type === 22) && obj.ownerID === myPlayer.id) {
          if (myPlayer.collidingSimple(obj, 300)) {
            sumX += obj.pos.current.x;
            sumY += obj.pos.current.y;
            count++;
            const d = myPlayer.pos.current.distance(obj.pos.current);
            if (d < nearestDist) {
              nearestDist = d;
              nearestTurret = obj;
            }
          }
        }
      });
      if (count === 0) {
        if (!myPlayer.canPlace(8)) return;
        this.grindAngle = ModuleHandler._currentAngle;
        let placed = false;
        const isSandbox = myPlayer.isSandbox;
        if (!isSandbox || farmItem === 22) {
          const spread = Math.PI / 180 * 40;
          if (this.placeTurret(this.grindAngle - spread)) placed = true;
          if (this.placeTurret(this.grindAngle + spread)) placed = true;
        } else {
          const spread = Math.PI / 180 * 75;
          if (this.placeTurret(this.grindAngle)) placed = true;
          if (this.placeTurret(this.grindAngle - spread)) placed = true;
          if (this.placeTurret(this.grindAngle + spread)) placed = true;
        }
        if (placed) {
          ModuleHandler.placedOnce = true;
          ModuleHandler.moduleActive = true;
        }
        return;
      }
      const centerX = sumX / count;
      const centerY = sumY / count;
      const middleAngle = Math.atan2(centerY - myPlayer.pos.current.y, centerX - myPlayer.pos.current.x);
      const action = this.getGrindAction(nearestTurret);
      if (action === null) return;
      if (reloading.isReloaded(action.weapon)) {
        ModuleHandler.moduleActive = true;
        ModuleHandler.useAngle = middleAngle;
        ModuleHandler.forceHat = action.hat;
        ModuleHandler.forceWeapon = action.weapon;
        ModuleHandler.shouldAttack = true;
      }
    }
  }
  // ModuleHandler.place() spends selectItem + attack + stopAttack + whichWeapon.
  const AUTOMILL_PLACE_COST = 5;
  // Clearance between the three automill windmills, in world units.
  //
  // canPlaceItem rejects a spot when the centre distance is BELOW
  // item.scale + neighbour.placementScale, so solving for exactly that bound
  // puts the two outer mills on the reject line itself. It also has to cover
  // the mixed-tier case: mills already on the ground keep the scale they were
  // placed at (windmill 45) while a newly upgraded one is 47, and 2 units is
  // the whole spread across the three tiers, so this clears the widest
  // neighbour a mill can land next to as well as its own tier.
  const AUTOMILL_ANGLE_MARGIN = 2;
  // ==========================================================================
  // Bot-only combat modules. Both live in ModuleHandler.botModules, so they run
  // for bots and never for the owner, and both go out through ModuleHandler —
  // no separate scheduler, no separate packet path.
  // ==========================================================================

  // Ranged secondaries a bot can kite with. Great hammer (10), shield (11) and
  // Mc Grabby (14) are the other secondaries and none of them shoot.
  const BOT_RANGED_SECONDARIES = new Set([ 9, 12, 13, 15 ]);

  // Sakuna's autobreak, for bots.
  //
  // Sakuna sweeps 360 one-degree directions, counts the blocking builds within
  // 90 degrees of each, takes the fullest direction, sorts those builds by
  // health and swings at the mean angle to them:
  //
  //     for (let i = 0; i < 2*PI; i += angleStep) { ...within PI/2... }
  //     bestDirection = buildsByDirection.reduce(longest)
  //     sortedByHealth = [...bestDirection].sort((a,b) => a.health - b.health)
  //     player.nearBreakAim = calculateMeanAngle(angles)
  //
  // The sweep is the expensive way to write it. The best direction always has a
  // blocking build within 90 degrees of it, so testing the directions of the
  // builds themselves finds the same maximum from n candidates instead of 360 —
  // same answer, and it cannot miss a cluster that falls between two steps.
  const BOT_BREAK_ARC = Math.PI / 2;
  // How slow counts as "not moving" — RYN's Entity.speed is the distance
  // covered last tick, so this is a fraction of a normal step.
  const BOT_BREAK_STUCK_SPEED = 8;
  // Ticks of being stuck before swinging. One stalled tick is a collision, three
  // in a row is something in the way.
  const BOT_BREAK_STUCK_TICKS = 3;
  const BOT_BREAK_RELEASE_TICKS = 2;

  class BotAutoBreak {
    moduleName="botAutoBreak";
    client;
    stuckTicks=0;
    freeTicks=0;
    target=null;
    constructor(client2) {
      this.client = client2;
    }
    reset() {
      this.stuckTicks = 0;
      this.freeTicks = 0;
      this.target = null;
    }

    // Mean of a set of angles, taken on the unit circle so that headings either
    // side of the +/-PI seam average to the direction between them rather than
    // to zero.
    _meanAngle(angles) {
      let sx = 0, sy = 0;
      for (let i = 0; i < angles.length; i++) {
        sx += Math.cos(angles[i]);
        sy += Math.sin(angles[i]);
      }
      if (sx === 0 && sy === 0) return angles[0] ?? 0;
      return Math.atan2(sy, sx);
    }

    // Everything within reach that could be what the bot is walking into.
    _blockers(myPlayer, ObjectManager2, PlayerManager2, reach) {
      const pos = myPlayer.pos.current;
      const out = [];
      ObjectManager2.grid2D.query(pos.x, pos.y, 2, id => {
        const obj = ObjectManager2.objects.get(id);
        if (obj === void 0 || !(obj instanceof PlayerObject)) return false;
        if (!obj.isDestroyable) return false;
        // Things you can walk over are never the reason you stopped.
        if (obj.canMoveOnTop()) return false;
        const d = pos.distance(obj.pos.current);
        if (d - obj.collisionScale > reach) return false;
        out.push({
          obj: obj,
          angle: pos.angle(obj.pos.current),
          dist: d
        });
        return false;
      });
      return out;
    }

    postTick() {
      if (!Settings_default._botAutoBreak) {
        this.reset();
        return;
      }
      const {myPlayer: myPlayer, _ModuleHandler: ModuleHandler, ObjectManager: ObjectManager2, PlayerManager: PlayerManager2} = this.client;
      if (!myPlayer || !myPlayer.inGame) {
        this.reset();
        return;
      }
      // Never fight a higher-priority action for the tick.
      if (ModuleHandler.moduleActive || ModuleHandler.placedOnce) return;

      // Stuck means: told to move, and not moving. A bot standing still because
      // nobody asked it to walk is not stuck.
      const wantsToMove = ModuleHandler.move_dir !== null && ModuleHandler.move_dir !== void 0;
      const moving = myPlayer.speed > BOT_BREAK_STUCK_SPEED;
      if (!wantsToMove || moving) {
        this.freeTicks++;
        if (this.freeTicks >= BOT_BREAK_RELEASE_TICKS) {
          this.stuckTicks = 0;
          this.target = null;
        }
        return;
      }
      this.freeTicks = 0;
      this.stuckTicks++;
      if (this.stuckTicks < BOT_BREAK_STUCK_TICKS) return;

      const primary = myPlayer.getItemByType(0);
      const secondary = myPlayer.getItemByType(1);
      // Sakuna breaks with the great hammer when it has one, otherwise the
      // primary — `player.weapons[1] == 10 ? weapons[1] : weapons[0]`.
      const useSecondary = secondary === 10;
      const weaponID = useSecondary ? secondary : primary;
      if (weaponID === null || weaponID === void 0) return;
      const weapon = DataHandler_default.getWeapon(weaponID);
      if (!weapon) return;
      const reloading = ModuleHandler.staticModules.reloading;
      if (!reloading.isReloaded(useSecondary ? 1 : 0)) return;

      const blockers = this._blockers(myPlayer, ObjectManager2, PlayerManager2, weapon.range ?? 0);
      if (blockers.length === 0) {
        this.target = null;
        return;
      }

      // Sakuna's fullest-direction pick, over the blockers' own directions.
      let best = null;
      for (let i = 0; i < blockers.length; i++) {
        const dir = blockers[i].angle;
        const group = [];
        for (let j = 0; j < blockers.length; j++) {
          if (getAngleDist(dir, blockers[j].angle) < BOT_BREAK_ARC) group.push(blockers[j]);
        }
        if (best === null || group.length > best.length) best = group;
      }
      if (best === null || best.length === 0) return;

      // Lowest health first, and swing at the mean direction of the group so one
      // swing covers as much of the wall as the arc allows.
      best.sort((a, b) => a.obj.health - b.obj.health);
      const aim = this._meanAngle(best.map(b => b.angle));

      ModuleHandler.moduleActive = true;
      ModuleHandler.useAngle = aim;
      ModuleHandler.forceWeapon = useSecondary ? 1 : 0;
      ModuleHandler.shouldAttack = true;
      this.target = best[0].obj;
    }
  }

  // ==========================================================================
  // Persistent exploration — how a scattered bot crosses the server.
  //
  // What was here before was x18's wander: pick a heading uniformly at random,
  // reject and re-roll it while it lands within 2 radians of the one it
  // replaces, then walk it until 3300 units of straight-line distance have
  // gone by, or 10 seconds pass, or the bot stops moving.
  //
  // A heading is not a destination. Re-rolling produces a random walk, and a
  // random walk goes nowhere in particular — expected displacement after n legs
  // grows with sqrt(n), so forty legs later a bot is still around the corner of
  // the map it started in, having covered a lot of ground to get there. The
  // forced turn made that worse rather than better: every accepted heading is
  // more than 115 degrees off the last one, so every leg has a component that
  // undoes the one before it. And the third re-roll condition fires on stopped,
  // which is what a bot is every time it walks into something — so against an
  // obstacle it re-rolled repeatedly, each time to a hard turn, which is the
  // part that reads as a bot flailing rather than exploring.
  //
  // This replaces the heading with a destination and a path to it:
  //
  //     current position -> a distant sector -> a corridor to it -> travel
  //     -> arrive -> another distant sector -> forever
  //
  // The bot commits to a destination and keeps it. Direction only changes for
  // a reason — the route bends around something, the destination is reached or
  // is proven unreachable, another bot is too close, or recovery from being
  // stuck. There is no per-tick randomness anywhere in the steering.
  //
  // It is roaming, not exploration. Nothing here records that a place has been
  // seen: there is no explored set, no frontier, no visited flag, and no way
  // for any part of the map to stop being a candidate. What there is instead is
  // a decaying penalty on the sector the bot is standing in, so it leaves; once
  // that runs out the sector is worth exactly what it was before the bot ever
  // arrived, and the bot will come back. The objective is coverage over time,
  // repeated indefinitely — a hundredth pass over the map is the same job as
  // the first.
  //
  // Layout, one concern per piece:
  //
  //   _expBlockerAt        what counts as solid, from the game's own collision
  //   _expCorridorClear    can the player's disc be swept along this segment
  //   _expClearHeading     nearest heading to the one we want that is clear
  //   _expBuildPath        destination -> waypoint list
  //   _expSpacingPass      bot-to-bot separation, one yielder per pair
  //   _expOwnerState       per-owner shared state: claims, plan budget
  //   BotExplorer          destination choice, following, stuck recovery,
  //                        route-relevant breaking, movement execution
  //
  // Everything underneath is the client's existing machinery: ObjectManager's
  // spatial grid for lookups, PlayerManager.canMoveOnTop for what is passable,
  // ModuleHandler.startMovement (which runs MovementSimulation) to actually
  // walk, and ModuleHandler's moduleActive/useAngle/forceWeapon/shouldAttack
  // channel — the same one BotAutoBreak uses — to swing at something. Nothing
  // here moves a player by any route the game does not already provide.
  // ==========================================================================

  const EXP_MAP = Config_default.mapScale;
  // The map divided into sectors. These are geography and nothing else — a way
  // of spreading destinations over the whole map instead of around wherever the
  // bot happens to be standing. There is no explored/unexplored state anywhere
  // in this file: every sector is eligible every time a destination is picked,
  // for as long as the client runs.
  const EXP_SECTOR_COLS = 6;
  const EXP_SECTOR_SIZE = EXP_MAP / EXP_SECTOR_COLS;
  // Keep destinations off the map wall; a point in the corner is a point the
  // bot arrives at by grinding along the boundary.
  const EXP_EDGE_MARGIN = 420;
  // A destination has to be a journey. 3200 is more than a screen width, so
  // "somewhere else" is somewhere the bot cannot currently see.
  const EXP_MIN_TRAVEL = 3200;
  // Distance is a qualifier, not a gradient. Past EXP_MIN_TRAVEL the trip is
  // already a journey and another few thousand units does not make it a better
  // one, so the term saturates: the whole far half of the map ties on distance
  // and the spread terms decide between them.
  //
  // Scoring raw distance instead measured as the bot bouncing between opposite
  // corners — the far rim beat everything else by a fixed margin no amount of
  // randomness could close, and barely half the map's sectors were ever chosen
  // as a destination. The middle of the map is somewhere to go, not only
  // somewhere to cross.
  const EXP_TRAVEL_SATURATION = 3000;
  const EXP_ARRIVE_RADIUS = 260;
  const EXP_NODE_RADIUS = 130;
  // Waypoint spacing, and how far ahead a corridor is probed. Beyond about this
  // the bot has no object knowledge to plan with anyway — the server only sends
  // what is near it — so a longer probe would be planning against an empty map.
  const EXP_PROBE = 420;
  const EXP_MAX_NODES = 5;
  // How far apart the grid is queried along a corridor. This is a lookup
  // stride, not a resolution: the distance test itself is exact against the
  // whole segment, so this only has to be close enough that every object near
  // the segment lands in some query's cells. A query with search=2 reaches at
  // least 200 units past the object's own footprint, and the widest thing on
  // the map is a tree at 175, so 150 leaves a wide margin.
  const EXP_QUERY_STRIDE = 150;
  // Where a corridor starts measuring, just past the player's own radius.
  // Without it, a bot already pressed against a wall reads every heading as
  // blocked, including the ones leading away from the wall.
  const EXP_SEGMENT_START = 40;
  // Slack beyond both collision radii before the corridor counts as passable.
  // This is what lets a path go through a gate: a gap is a gap when the
  // player's disc fits in it, and the game's collision says exactly when it
  // does.
  const EXP_CLEARANCE = 6;
  const EXP_FAN_STEP = Math.PI / 12;
  const EXP_FAN_LIMIT = Math.PI * 0.62;
  const EXP_NO_BACKTRACK = Math.PI * 0.62;
  // Movement is only re-sent when the heading actually moves. Below this the
  // change is not worth a packet and re-sending it is exactly the jitter this
  // system exists to remove.
  const EXP_HEADING_DEADBAND = 0.06;
  const EXP_MOVE_KEEPALIVE_MS = 2e3;
  const EXP_REPATH_COOLDOWN_MS = 700;
  const EXP_VALIDATE_MS = 300;
  // Matches BOT_BREAK_STUCK_SPEED: Entity.speed is the distance covered last
  // tick, so this is a fraction of a normal step rather than a true zero.
  const EXP_STUCK_SPEED = 8;
  const EXP_STUCK_TICKS = 6;
  const EXP_PROGRESS_WINDOW_MS = 2500;
  const EXP_PROGRESS_MIN = 160;
  const EXP_RECOVERY_STEP_MS = 1200;
  // Recovery steps before a destination is written off. Step 1 reroutes the
  // other way round; from step 2 breaking is on the table, and the steps after
  // it are the time a wall gets to come down before the bot decides the whole
  // destination is the problem.
  const EXP_RECOVERY_GIVE_UP = 6;
  const EXP_RECOVERY_BREAK_AT = 2;
  // A sector the bot could not reach is skipped for this long. This is about
  // reachability, not about having been there: it is set by the stuck ladder
  // giving up, never by arriving, and it expires on its own.
  const EXP_SECTOR_FAIL_MS = 6e4;
  // How long a sector the bot has just stood in is worth less than the rest of
  // the map. Not a visited flag — a decaying penalty that reaches zero, after
  // which the sector scores exactly as it did before the bot ever went there.
  // This is the whole of the "do not loop around one region" rule.
  const EXP_SECTOR_COOLDOWN_MS = 9e4;

  // Destination scoring. Every term is a preference; none of them is a filter,
  // so no part of the map can ever become permanently ineligible.
  const EXP_W_DISTANCE = .6;     // far enough to be a journey
  const EXP_W_BEARING = .9;      // away from the last leg's direction
  const EXP_W_EDGE = .12;        // a tiebreak toward the boundary, no more
  const EXP_W_RANDOM = .55;      // route variation between near-equal sectors
  const EXP_W_RECENT = 1;        // where the bot has just been, for a while
  const EXP_W_HISTORY = 1;       // near one of its own last few destinations
  const EXP_W_FLEET = 1.2;       // near where another bot is already heading
  // How far apart the fleet's destinations are pulled. Inside this radius a
  // sector is worth less to a bot the closer it is to another bot's target, so
  // a fleet fans out across the map instead of arriving together.
  const EXP_FLEET_SPREAD = 4200;
  // Chance that a destination in a sector on the map boundary is put on the
  // boundary itself rather than in the middle of the sector, so the four edges
  // and the four corners get visited rather than merely passed near.
  const EXP_EDGE_PULL_CHANCE = .5;
  const EXP_EDGE_BAND = 300;
  // Hard cap on one destination, so a bot that is making slow progress rather
  // than no progress still moves on eventually.
  const EXP_DEST_TIMEOUT_MS = 9e4;
  const EXP_DEST_HISTORY = 8;
  const EXP_DEST_MIN_SEPARATION = 2200;
  const EXP_SPACING_RADIUS = 260;
  const EXP_SPACING_COOLDOWN_MS = 6e3;
  const EXP_SPACING_INTERVAL_MS = 500;
  const EXP_BREAK_ARC = Math.PI / 2.4;
  // Path building is the only expensive thing here, so it runs on a budget
  // shared by the whole fleet: at most this many plans per window, whatever the
  // bot count. A bot waiting for a token still walks — see _headingFor.
  const EXP_PLAN_WINDOW_MS = 100;
  const EXP_PLAN_PER_WINDOW = 3;

  const _expOwnerStates = new WeakMap;

  function _expOwnerState(owner) {
    let state = _expOwnerStates.get(owner);
    if (state === undefined) {
      state = {
        spacingRan: 0,
        planWindow: 0,
        planTokens: EXP_PLAN_PER_WINDOW,
        claims: new Map
      };
      _expOwnerStates.set(owner, state);
    }
    return state;
  }

  function _expSectorAt(x, y) {
    const sx = clamp(Math.floor(x / EXP_SECTOR_SIZE), 0, EXP_SECTOR_COLS - 1);
    const sy = clamp(Math.floor(y / EXP_SECTOR_SIZE), 0, EXP_SECTOR_COLS - 1);
    return sy * EXP_SECTOR_COLS + sx;
  }

  // Where each bot is currently heading, so the next bot to choose can head
  // somewhere else. Two bots walking to the same corner is the clustering this
  // exists to prevent, and it is cheaper to avoid at the moment of choosing
  // than to separate them once they have both arrived.
  function _expClaim(owner, bot, point) {
    const state = _expOwnerState(owner);
    if (point === null) {
      state.claims.delete(bot);
      return;
    }
    state.claims.set(bot, {
      x: point.x,
      y: point.y
    });
  }

  // How crowded a candidate point is by the rest of the fleet's destinations:
  // 0 when nobody else is heading within EXP_FLEET_SPREAD of it, rising toward
  // 1 per bot as they converge. A distance falloff rather than a same-sector
  // test, because two bots either side of a sector line are still together.
  function _expCrowding(owner, bot, x, y) {
    const state = _expOwnerState(owner);
    let crowding = 0;
    for (const [other, claim] of state.claims) {
      if (other === bot) {
        continue;
      }
      const d = Math.hypot(claim.x - x, claim.y - y);
      if (d < EXP_FLEET_SPREAD) {
        crowding += 1 - d / EXP_FLEET_SPREAD;
      }
    }
    return crowding;
  }

  function _expTakePlanToken(owner, now) {
    const state = _expOwnerState(owner);
    if (now - state.planWindow >= EXP_PLAN_WINDOW_MS) {
      state.planWindow = now;
      state.planTokens = EXP_PLAN_PER_WINDOW;
    }
    if (state.planTokens <= 0) {
      return false;
    }
    state.planTokens -= 1;
    return true;
  }

