          let score = Math.min(1, (dist - EXP_MIN_TRAVEL) / EXP_TRAVEL_SATURATION) * EXP_W_DISTANCE;
          // A different direction from the leg just walked, so the bot crosses
          // the map rather than shuffling along one side of it.
