(function rynBotToastSetup() {
    if (typeof window === "undefined") return;
    window._rynBotToast = function (msg) {
        try {
            let t = document.getElementById("rynBotToast");
            if (!t) {
                t = document.createElement("div");
                t.id = "rynBotToast";
                t.style.cssText = "position:fixed;left:50%;bottom:70px;transform:translateX(-50%);z-index:2147483647;background:rgba(0,0,0,0.8);color:#9090f8;font-family:sans-serif;font-size:14px;padding:8px 16px;border-radius:8px;border:1px solid #9090c8;pointer-events:none;transition:opacity .3s;";
                (document.body || document.documentElement).appendChild(t);
            }
            t.textContent = msg;
            t.style.opacity = "1";
            clearTimeout(t._to);
            t._to = setTimeout(() => { t.style.opacity = "0"; }, 1800);
        } catch (e) {}
    };
})();
